const echo=new THREE.Group();echo.position.set(2,0,9);world.add(echo);const echoBody=sphere(echo,[0,1.15,0],.5,new THREE.MeshStandardMaterial({color:0x4fe9df,transparent:true,opacity:.32,emissive:0x38d7d1,emissiveIntensity:1.6,roughness:.2}),16);echoBody.scale.set(.7,1.6,.5);const echoHead=sphere(echo,[0,2.1,0],.32,echoBody.material,16);const echoRing=new THREE.Mesh(new THREE.TorusGeometry(.8,.025,6,36),glowMat);echoRing.position.y=.35;echo.add(echoRing);const echoLight=new THREE.PointLight(0x56e6dc,2,6);echoLight.position.y=2;echo.add(echoLight);

let yaw=0,pitch=.12,keys={},joy={x:0,y:0},dragging=false,lastTouch=null,elapsed=0,dialogueLines=[],lineIndex=0,dialogueOpen=false,journal=[];
const saveKey='museum-tomorrow-save-v1';
function save(){try{localStorage.setItem(saveKey,JSON.stringify({solved:state.solved,journey:journal,ended:state.ended||false}))}catch(e){}}
function load(){try{const d=JSON.parse(localStorage.getItem(saveKey)||'null');if(d){state.solved=d.solved||[false,false,false];journal=d.journey||[];state.ended=d.ended||false;return true}}catch(e){}return false}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function updateProgress(){state.solved.forEach((v,i)=>$('#d'+i).classList.toggle('done',v));const n=state.solved.filter(Boolean).length;const titles=['Menit yang Hilang','Mesin yang Mengingat','Saksi dari Esok'];const texts=['Temukan jejak artefak yang lenyap. Dengarkan gema di aula.','Pulihkan aliran daya pada Turbin Arsip.','Baca pesan yang tertinggal oleh Penjaga.'];$('#objectiveTitle').textContent=n<3?titles[n]:'Pameran Terakhir';$('#objectiveText').textContent=n<3?texts[n]:'Tiga anomali selaras. Kembali ke gerbang pusat.';$('.objective small').textContent=`INVESTIGASI · ${String(Math.min(n+1,3)).padStart(2,'0')} / 03`;save()}
function markSolved(i,msg){if(state.solved[i])return;state.solved[i]=true;updateProgress();showToast(msg);journal.push(msg);if(state.solved.every(Boolean)){showToast('GERBANG PAMERAN TERAKHIR TERBUKA');$('#objectiveText').textContent='Kembali ke portal pusat. Sesuatu sedang menunggu.';}}
function setTime(t){state.time=t;document.querySelectorAll('.time-btn').forEach(b=>b.classList.toggle('active',b.dataset.state===t));const cap={past:'MASA LALU · INGATAN',present:'MASA KINI · PENGAMATAN',future:'MASA DEPAN · KEMUNGKINAN'};$('#timeCaption').textContent=cap[t];if(state.active)applyTemporal(state.active,t)}
function applyTemporal(obj,t){obj.userData.state=t;const d=obj.userData;if(d.kind==='bridge'){for(let i=0;i<5;i++){const tile=d.parts['tile'+i];tile.visible=t==='past'||i<3;tile.position.y=t==='past'?-.05:(i<3?-.05:-2.3);tile.material=t==='past'?goldMat:(i<3?trimMat:glowMat)}$('#timeCaption').textContent=`JEMBATAN · ${t.toUpperCase()}`}
if(d.kind==='turbine'){rotor.rotation.z=t==='future'?Math.PI/4:0;beam.visible=t==='future';sphere(turbine,[0,2.55,0],.34,t==='future'?glowMat:goldMat);$('#timeCaption').textContent=`TURBIN · ${t.toUpperCase()}`}
if(d.kind==='statue'){sigil.visible=t==='future';figure.material=t==='past'?goldMat:trimMat;$('#timeCaption').textContent=`PENJAGA · ${t.toUpperCase()}`}
}
function openDialogue(speaker,lines){dialogueLines=lines;lineIndex=0;dialogueOpen=true;$('#speaker').textContent=speaker;$('#dialog').style.display='block';$('#dialogText').textContent=lines[0];$('#dialogNext').textContent=lines.length>1?'LANJUTKAN ↗':'TUTUP ×';}
function nextDialogue(){lineIndex++;if(lineIndex>=dialogueLines.length){dialogueOpen=false;$('#dialog').style.display='none';return}$('#dialogText').textContent=dialogueLines[lineIndex];$('#dialogNext').textContent=lineIndex===dialogueLines.length-1?'TUTUP ×':'LANJUTKAN ↗'}
$('#dialogNext').onclick=nextDialogue;
function interact(){if(dialogueOpen){nextDialogue();return}if(!state.near){return}const target=state.near;if(target===echo){openDialogue('ECHO · MUSEUM AI',['Selamat datang, Penjaga Arka. Jadwal shift Anda... tidak tercatat.','Artefak utama, “Menit Pertama”, telah hilang. Tanpa itu, kemungkinan-kemungkinan di dalam museum akan runtuh.','Saya mendengar gema di antara objek. Ubah waktunya. Jangan percaya apa pun yang hanya memiliki satu versi.']);journal.push('ECHO: artefak utama hilang. Objek menyimpan tiga versi waktu.');return}
const d=target.userData;if(d.kind==='bridge'){if(state.time==='past'){markSolved(0,'JEMBATAN MEMORI · JALUR TERPULIHKAN');}else showToast('BENTUK INI BELUM BISA DILEWATI · COBA PAST');}
else if(d.kind==='turbine'){if(state.time==='future'){markSolved(1,'TURBIN ARSIP · DAYA MENYALA');}else showToast('TURBIN MENUNGGU KEMUNGKINAN MASA DEPAN');}
else if(d.kind==='statue'){if(state.time==='future'){markSolved(2,'PESAN PENJAGA · “AKU ADALAH ARKA.”');openDialogue('INSKRIPSI TERSEMBUNYI',['“Jika kau membaca ini, museum telah memilihmu dua kali.”','“Aku bukan pencipta tempat ini. Aku adalah penjaga terakhir—dan yang pertama.”','Wajah di patung itu... mirip dengan wajahmu.']);}else showToast('PATUNG MENYIMPAN SESUATU DI MASA DEPAN');}
}
function getNearest(){let nearest=null,dist=99;for(const o of interactables){if(!o.visible)continue;const d=player.position.distanceTo(o.getWorldPosition(new THREE.Vector3()));if(d<dist){dist=d;nearest=o}}const de=player.position.distanceTo(echo.position);if(de<dist){dist=de;nearest=echo}return dist<3.7?nearest:null}
function updatePrompt(){state.near=getNearest();const p=$('#prompt'),text=$('#promptText'),label=state.near?(state.near===echo?'BERBICARA DENGAN ECHO':state.near.userData.label):'';$('#target').textContent=label;p.style.display=state.near&&!dialogueOpen?'block':'none';text.textContent=label}
function collect(){for(let i=collectibles.length-1;i>=0;i--){const o=collectibles[i];if(player.position.distanceTo(o.position)<1.15){world.remove(o);collectibles.splice(i,1);showToast('FRAGMEN INGATAN · '+String(i+1).padStart(2,'0'));journal.push('Fragmen ingatan ditemukan.');save()}}}
function move(dt){if(!state.started||dialogueOpen)return;const f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-joy.y;const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joy.x;let v=new THREE.Vector3(side,0,-f);if(v.lengthSq()>1)v.normalize();if(v.lengthSq()){const speed=(state.run||keys.ShiftLeft||keys.ShiftRight?7.4:4.4)*dt;const forward=new THREE.Vector3(Math.sin(yaw),0,-Math.cos(yaw));const right=new THREE.Vector3(Math.cos(yaw),0,Math.sin(yaw));player.position.addScaledVector(forward,f*speed);player.position.addScaledVector(right,side*speed);player.rotation.y=Math.atan2(v.x,-v.z)+yaw;legs.forEach((l,i)=>l.rotation.x=Math.sin(elapsed*12+i*Math.PI)*.5)}player.position.x=THREE.MathUtils.clamp(player.position.x,-15.2,15.2);player.position.z=THREE.MathUtils.clamp(player.position.z,-31.5,20);if(player.position.z<-5&&Math.abs(player.position.x)<3.1&&!state.solved[0])player.position.z=-5;}
function updateCamera(dt){const behind=new THREE.Vector3(Math.sin(yaw)*6,3.15,Math.cos(yaw)*6);const desired=player.position.clone().add(behind);desired.y+=pitch*2;camera.position.lerp(desired,1-Math.pow(.001,dt));const look=player.position.clone().add(new THREE.Vector3(0,1.55,0));look.add(new THREE.Vector3(Math.sin(yaw)*1.5,0,-Math.cos(yaw)*1.5));camera.lookAt(look)}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.035);elapsed+=dt;move(dt);updateCamera(dt);monument.rotation.y=elapsed*.11;monument.position.y=8+Math.sin(elapsed*.6)*.22;echo.position.y=Math.sin(elapsed*1.6)*.12;echoRing.rotation.y=elapsed*.5;rotor.rotation.z+=state.solved[1]?.018:0;particles.rotation.y=elapsed*.005;interactables.forEach(o=>{if(o.userData.kind==='statue'&&o.userData.state==='future')sigil.material.emissiveIntensity=1.5+Math.sin(elapsed*4)*.7});updatePrompt();collect();renderer.render(scene,camera)}

