function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.035);elapsed+=dt;move(dt);updateCamera(dt);monument.rotation.y=elapsed*.11;monument.position.y=8+Math.sin(elapsed*.6)*.22;echo.position.y=Math.sin(elapsed*1.6)*.12;echoRing.rotation.y=elapsed*.5;rotor.rotation.z+=state.solved[1]?.018:0;particles.rotation.y=elapsed*.005;interactables.forEach(o=>{if(o.userData.kind==='statue'&&o.userData.state==='future')sigil.material.emissiveIntensity=1.5+Math.sin(elapsed*4)*.7});updatePrompt();collect();if(state.solved.every(Boolean)&&player.position.z<-29&&Math.abs(player.position.x)<3.2&&!state.ended){state.ended=true;save();openDialogue('THE LAST EXHIBITION',['The central portal opens without a sound. Beyond it: an empty room, and a single object suspended in the dark.','The missing Minute is not an artifact. It is the moment before every choice—the museum’s first possible future.','A figure waits in the glass. It wears Arka’s face. “You came back,” it says. “Which version of tomorrow should remain?”']);setTimeout(()=>showEndingChoice(),900)}renderer.render(scene,camera)}

function openModal(html){$('#modalCard').innerHTML=html;$('#modal').classList.add('open');state.wasStarted=state.started;state.started=false;}
function closeModal(){ $('#modal').classList.remove('open');if(state.wasStarted)state.started=true; }
function showSettings(){openModal(`<h2>Pengaturan</h2><p class="sub">SESUAIKAN SHIFT ANDA</p><label>BAHASA / LANGUAGE</label><select id="lang"><option value="id">Bahasa Indonesia</option><option value="en">English (coming soon)</option></select><label>KUALITAS GRAFIS</label><select id="quality"><option>Low</option><option selected>Medium</option><option>High</option><option>Ultra</option></select><label>SENSITIVITAS KAMERA</label><input id="sens" type="range" min=".3" max="2" step=".1" value="1"><p style="font-size:10px">Grafis adaptif · bayangan real-time · kualitas dapat disesuaikan untuk menjaga performa.</p><div class="actions"><button id="settingsSave" class="primary">SELESAI</button></div>`);$('#settingsSave').onclick=()=>{const q=$('#quality').value;renderer.setPixelRatio(Math.min(devicePixelRatio,q==='Low'?.85:q==='Medium'?1.2:q==='High'?1.6:2));camera.userData.sensitivity=Number($('#sens').value);closeModal()}}
function showMap(){openModal(`<h2>Atlas kemungkinan</h2><p class="sub">MUSEUM OF TOMORROW · 6 PAVILION</p><div class="map-list"><div class="map-cell">01 · THE ENTRANCE<span>AKTIF · 3 ANOMALI</span></div><div class="map-cell">02 · THE LOST CITY<span>TERSEGEL · MENUNGGU FRAGMEN</span></div><div class="map-cell">03 · THE OCEAN MEMORY<span>TERSEGEL</span></div><div class="map-cell">04 · THE SILENT PLANET<span>TERSEGEL</span></div><div class="map-cell">05 · THE BROKEN FUTURE<span>ANOMALI TERDETEKSI</span></div><div class="map-cell">06 · THE LAST EXHIBITION<span>${state.solved.every(Boolean)?'GERBANG TERBUKA':'TERSEGEL · 3 KUNCI'}</span></div></div><div class="actions"><button id="mapClose" class="primary">KEMBALI</button></div>`);$('#mapClose').onclick=closeModal}
